    "title": {
      "type": "Text",
      "props": {
        "text": "Mid-Range AI & Camera Phone Showdown",
        "variant": "h2"
      },
      "children": []
    },
    "intro_text": {
      "type": "Text",
      "props": {
        "text": "This comparison evaluates four mid-range Android phones, focusing on their on-device AI capabilities for note-taking and their camera systems. The analysis uses the specifications you provided.",
        "variant": "body"
      },
      "children": []
    },
    "context_title": {
      "type": "Text",
      "props": {
        "text": "Evaluation Context",
        "variant": "h3"
      },
      "children": []
    },
    "context_text": {
      "type": "Text",
      "props": {
        "text": "The Google Pixel 8a is a real-world device. The Samsung Galaxy A56, Nothing Phone 3a Pro, and OnePlus 13R are treated as hypothetical models for this direct comparison.",
        "variant": "body"
      },
      "children": []
    },
    "breakdown_title": {
      "type": "Text",
      "props": {
        "text": "Feature Breakdown",
        "variant": "h2"
      },
      "children": []
    },
    "breakdown_intro": {
