          {
            "key": "feature",
            "label": "Feature"
          },
          {
            "key": "value",
            "label": "Value"
          }
        ],
        "rows": [
          {
            "feature": "Price",
            "value": "USD 499"
          },
          {
            "feature": "Chipset & AI",
            "value": "Tensor G3 (Optimized for on-device Google AI)"
          },
          {
            "feature": "RAM / Storage",
            "value": "8 GB / 128 GB"
          },
          {
            "feature": "Camera",
            "value": "64 MP Main"
          },
          {
            "feature": "Key Features",
            "value": "Exclusive AI call notes, best-in-class 7 years of OS updates."
