      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "md"
      },
      "children": [
        "top_pick_card",
        "performance_card",
        "value_card"
      ]
    },
    "top_pick_card": {
      "type": "Card",
      "props": {},
      "children": [
        "top_pick_stack"
      ]
    },
    "top_pick_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
