      "children": [
        "top_pick_title_stack",
        "top_pick_text"
      ]
    },
    "top_pick_title_stack": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "md",
        "align": "center"
      },
      "children": [
        "top_pick_icon",
        "top_pick_title"
      ]
    },
    "top_pick_icon": {
      "type": "Icon",
      "props": {
        "name": "../assets/r_000003_01_2_star-fill.svg"
      },
      "children": []
    },
    "top_pick_title": {
      "type": "Text",
      "props": {
        "text": "Top Pick for AI & Camera: Google Pixel 8a",
        "variant": "h3"
      },
      "children": []
    },
    "top_pick_text": {
      "type": "Text",
      "props": {
        "text": "The Pixel 8a is the strongest choice for your specific needs. Its Tensor G3 chip is custom-built for Google's on-device AI, directly supporting features like AI-powered notes. It also has the highest resolution main camera and an unmatched 7-year software update promise, ensuring long-term security and feature availability.",
        "variant": "body"
      },
      "children": []
    },
    "performance_card": {
      "type": "Card",
      "props": {},
      "children": [
        "performance_stack"
      ]
    },
    "performance_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "performance_title_stack",
        "performance_text"
      ]
    },
    "performance_title_stack": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "md",
        "align": "center"
      },
      "children": [
        "performance_icon",
        "performance_title"
      ]
    },
    "performance_icon": {
      "type": "Icon",
      "props": {
        "name": "../assets/r_000003_01_12_speedometer2.svg"
      },
      "children": []
