      "type": "Text",
      "props": {
        "text": "Best for Raw Performance: OnePlus 13R",
        "variant": "h3"
      },
      "children": []
    },
    "performance_text": {
      "type": "Text",
      "props": {
        "text": "If raw processing power is a priority for heavy multitasking or gaming alongside AI tasks, the OnePlus 13R is the clear winner. Its flagship-grade Snapdragon 8 Gen 3 processor and 12 GB of RAM offer the most performance, though it comes at the highest price in this group.",
        "variant": "body"
      },
      "children": []
    },
    "value_card": {
      "type": "Card",
      "props": {},
      "children": [
        "value_stack"
      ]
    },
    "value_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "value_title_stack",
        "value_text"
      ]
    },
    "value_title_stack": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "md",
        "align": "center"
      },
