      },
      "children": []
    },
    "actions_title": {
      "type": "Text",
      "props": {
        "text": "Quick Actions",
        "variant": "h2"
      },
      "children": []
    },
    "actions_stack": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "md"
      },
      "children": [
        "button_compare",
        "button_deals"
      ]
    },
    "button_compare": {
      "type": "Button",
      "props": {
        "label": "Compare Smartphone Prices",
        "variant": "primary"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://shopping.google.com/search?q=mid-range+android+phone"
          }
        }
      },
      "children": []
    },
    "button_deals": {
      "type": "Button",
      "props": {
        "label": "View Latest Phone Deals",
        "variant": "borderless"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.gsmarena.com/deals.php3"
          }
        }
      },
      "children": []
    }
